    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            if v:
                positions[v].append((r, c))

    frames = []
    for color, pts in positions.items():
        r0 = min(r for r, _ in pts)
        r1 = max(r for r, _ in pts)
        c0 = min(c for _, c in pts)
        c1 = max(c for _, c in pts)
        if r1 - r0 < 2 or c1 - c0 < 2:
            continue
        if not (all(grid[r0][c] == color for c in range(c0, c1 + 1))
                and all(grid[r1][c] == color for c in range(c0, c1 + 1))
                and all(grid[r][c0] == color for r in range(r0, r1 + 1))
                and all(grid[r][c1] == color for r in range(r0, r1 + 1))):
            continue
        pattern = [[grid[r][c] == color for c in range(c0 + 1, c1)]
                   for r in range(r0 + 1, r1)]
        frames.append({"color": color, "r0": r0, "r1": r1, "c0": c0, "c1": c1,
                       "pattern": pattern, "filled": any(map(any, pattern))})

    sources = [f for f in frames if f["filled"]]
    if not sources:
        return [row[:] for row in grid]
    # The patterned frame is the template.
    source = max(sources, key=lambda f: sum(sum(row) for row in f["pattern"]))
    out = [row[:] for row in grid]

